from __future__ import annotations

import ast
import io
import re
import tokenize
from pathlib import Path

_ROOT = Path(__file__).resolve().parents[1]
_SRC = _ROOT / "src" / "equimel"

_HARD_PHRASES = (
    "reproduction of",
    "based on the paper",
    "re-implementation",
    "following the authors",
    "as described by",
    "generated by",
    "ai-assisted",
    "ai assisted",
    "skeleton",
    "placeholder",
    "todo from paper",
    "cutting-edge",
    "state-of-the-art",
    "seamlessly",
    "meticulously",
    "it's worth noting",
    "in conclusion",
)

_PROSE_WORDS = ("utilize", "leverage", "comprehensive", "delve", "holistic")

_EMOJI = re.compile(
    "[\U0001f000-\U0001faff\U00002600-\U000027bf\U0001f1e6-\U0001f1ff"
    "\U00002b00-\U00002bff\U0000fe00-\U0000fe0f]"
)


def _source_files() -> list[Path]:
    return sorted(_SRC.rglob("*.py"))


def _scan_files() -> list[Path]:
    pool = list(_source_files())
    pool += [_ROOT / "README.md", _ROOT / "Makefile"]
    pool += sorted((_ROOT / "configs").rglob("*.gin"))
    pool += sorted((_ROOT / "scripts").rglob("*.sh"))
    return [path for path in pool if path.exists()]


def test_source_has_no_comments_or_docstrings() -> None:
    for path in _source_files():
        text = path.read_text(encoding="utf-8")
        for token in tokenize.generate_tokens(io.StringIO(text).readline):
            assert token.type != tokenize.COMMENT, f"{path}:{token.start[0]}"
        tree = ast.parse(text)
        definition = ast.Module | ast.FunctionDef | ast.AsyncFunctionDef | ast.ClassDef
        for node in ast.walk(tree):
            if isinstance(node, definition):
                assert ast.get_docstring(node) is None, str(path)


def test_no_forbidden_phrases() -> None:
    for path in _scan_files():
        lowered = path.read_text(encoding="utf-8").lower()
        for phrase in _HARD_PHRASES:
            assert phrase not in lowered, f"{path}: {phrase}"


def test_no_emoji() -> None:
    for path in _scan_files():
        assert _EMOJI.search(path.read_text(encoding="utf-8")) is None, str(path)


def test_prose_avoids_marketing_words() -> None:
    prose = [_ROOT / "README.md", _ROOT / "Makefile"]
    prose += sorted((_ROOT / "scripts").rglob("*.sh"))
    for path in prose:
        if not path.exists():
            continue
        lowered = path.read_text(encoding="utf-8").lower()
        for word in _PROSE_WORDS:
            assert word not in lowered, f"{path}: {word}"
